#include <stdbool.h>
#include <stdint.h>

/*----------------------------------------------------------------------------
| Scales extended double-precision floating-point value in operand `a' by
| value `b'. The function truncates the value in the second operand 'b' to
| an integral value and adds that value to the exponent of the operand 'a'.
| The operation performed according to the IEC/IEEE Standard for Binary
| Floating-Point Arithmetic.
*----------------------------------------------------------------------------*/

extFloat80_t extF80_scale(extFloat80_t a, extFloat80_t b, softfloat_status_t *status)
{
    uint16_t uiA64;
    uint64_t uiA0;
    bool signA;
    int32_t expA;
    uint64_t sigA;
    uint16_t uiB64;
    uint64_t uiB0;
    bool signB;
    int32_t expB;
    uint64_t sigB;
    struct exp32_sig64 normExpSig;

    // handle unsupported extended double-precision floating encodings
    if (extF80_isUnsupported(a) || extF80_isUnsupported(b)) {
invalid:
        softfloat_raiseFlags(status, softfloat_flag_invalid);
        return packToExtF80(defaultNaNExtF80UI64, defaultNaNExtF80UI0);
    }

    /*------------------------------------------------------------------------
    *------------------------------------------------------------------------*/
    uiA64 = a.signExp;
    uiA0  = a.signif;
    signA = signExtF80UI64(uiA64);
    expA  = expExtF80UI64(uiA64);
    sigA  = uiA0;
    uiB64 = b.signExp;
    uiB0  = b.signif;
    signB = signExtF80UI64(uiB64);
    expB  = expExtF80UI64(uiB64);
    sigB  = uiB0;
    /*------------------------------------------------------------------------
    *------------------------------------------------------------------------*/

    if (expA == 0x7FFF) {
        if ((sigA<<1) || ((expB == 0x7FFF) && (sigB<<1))) {
            return softfloat_propagateNaNExtF80UI(uiA64, uiA0, uiB64, uiB0, status);
        }
        if ((expB == 0x7FFF) && signB) goto invalid;
        if (sigB && !expB) softfloat_raiseFlags(status, softfloat_flag_denormal);
        return a;
    }
    if (expB == 0x7FFF) {
        if (sigB<<1) {
            return softfloat_propagateNaNExtF80UI(uiA64, uiA0, uiB64, uiB0, status);
        }
        if ((expA | sigA) == 0) {
            if (! signB) goto invalid;
            return a;
        }
        if (sigA && !expA) softfloat_raiseFlags(status, softfloat_flag_denormal);
        if (signB) return packToExtF80(signA, 0, 0);
        return packToExtF80(signA, 0x7FFF, BX_CONST64(0x8000000000000000));
    }
    if (! expA) {
        if (sigB && !expB) softfloat_raiseFlags(status, softfloat_flag_denormal);
        if (! sigA) return a;
        softfloat_raiseFlags(status, softfloat_flag_denormal);
        normExpSig = softfloat_normSubnormalExtF80Sig(sigA);
        expA = normExpSig.exp + 1;
        sigA = normExpSig.sig;
        if (expB < 0x3FFF)
            return softfloat_normRoundPackToExtF80(signA, expA, sigA, 0, 80, status);
    }
    if (!expB) {
        if (!sigB) return a;
        softfloat_raiseFlags(status, softfloat_flag_denormal);
        normExpSig = softfloat_normSubnormalExtF80Sig(sigB);
        expB = normExpSig.exp + 1;
        sigB = normExpSig.sig;
    }

    if (expB > 0x400E) {
        /* |scale| is so large here that the true (unbounded) result exponent
           is always far beyond the +-0x6000 unmasked-exception wrap window,
           no matter what expA is - so this is unrescuable overflow/underflow.
           Feed roundPackToExtF80 a real expA + scale (not a boundary sentinel
           equal to the wrap target) so its overflow/underflow detection - and
           the +-0x6000 wrap it performs for unmasked exceptions - resolves to
           the correct infinity / zero instead of accidentally landing back in
           the representable range. */
        int32_t scale = signB ? -0x10000 : 0x10000;
        return softfloat_roundPackToExtF80(signA, expA + scale, sigA, 0, 80, status);
    }

    if (expB < 0x3FFF) return a;

    int shiftCount = 0x403E - expB;
    sigB >>= shiftCount;
    int32_t scale = (int32_t) sigB;
    if (signB) scale = -scale; /* -32768..32767 */

    return softfloat_roundPackToExtF80(signA, expA + scale, sigA, 0, 80, status);
}
