#include <stdbool.h>
#include <stdint.h>

float128_t f128_div(float128_t a, float128_t b, uint8_t roundingMode, uint8_t roundingPrecision, struct softfloat_status_t *status)
{
    uint64_t uiA64, uiA0;
    bool signA;
    int32_t expA;
    struct uint128 sigA;
    uint64_t uiB64, uiB0;
    bool signB;
    int32_t expB;
    struct uint128 sigB;
    bool signZ;
    struct exp32_sig128 normExpSig;
    int32_t expZ;
    struct uint128 rem;
    uint32_t recip32;
    int ix;
    uint64_t q64;
    uint32_t q;
    struct uint128 term;
    uint32_t qs[3];
    uint64_t sigZExtra;
    struct uint128 sigZ, uiZ;

    /*------------------------------------------------------------------------
    *------------------------------------------------------------------------*/
    uiA64 = a.v64;
    uiA0  = a.v0;
    signA = signF128UI64(uiA64);
    expA  = expF128UI64(uiA64);
    sigA.v64 = fracF128UI64(uiA64);
    sigA.v0  = uiA0;
    uiB64 = b.v64;
    uiB0  = b.v0;
    signB = signF128UI64(uiB64);
    expB  = expF128UI64(uiB64);
    sigB.v64 = fracF128UI64(uiB64);
    sigB.v0  = uiB0;
    signZ = signA ^ signB;
    /*------------------------------------------------------------------------
    *------------------------------------------------------------------------*/
    if (expA == 0x7FFF) {
        if (sigA.v64 | sigA.v0) goto propagateNaN;
        if (expB == 0x7FFF) {
            if (sigB.v64 | sigB.v0) goto propagateNaN;
            goto invalid;
        }
        goto infinity;
    }
    if (expB == 0x7FFF) {
        if (sigB.v64 | sigB.v0) goto propagateNaN;
        goto zero;
    }
    /*------------------------------------------------------------------------
    *------------------------------------------------------------------------*/
    if (! expB) {
        if (! (sigB.v64 | sigB.v0)) {
            if (! (expA | sigA.v64 | sigA.v0)) goto invalid;
            softfloat_raiseFlags(status, softfloat_flag_infinite);
            goto infinity;
        }
        normExpSig = softfloat_normSubnormalF128Sig(sigB.v64, sigB.v0);
        expB = normExpSig.exp;
        sigB = normExpSig.sig;
    }
    if (! expA) {
        if (! (sigA.v64 | sigA.v0)) goto zero;
        normExpSig = softfloat_normSubnormalF128Sig(sigA.v64, sigA.v0);
        expA = normExpSig.exp;
        sigA = normExpSig.sig;
    }
    /*------------------------------------------------------------------------
    *------------------------------------------------------------------------*/
    expZ = expA - expB + 0x3FFE;
    sigA.v64 |= UINT64_C(0x0001000000000000);
    sigB.v64 |= UINT64_C(0x0001000000000000);
    rem = sigA;
    if (softfloat_lt128(sigA.v64, sigA.v0, sigB.v64, sigB.v0)) {
        --expZ;
        rem = softfloat_add128(sigA.v64, sigA.v0, sigA.v64, sigA.v0);
    }
    recip32 = softfloat_approxRecip32_1(sigB.v64>>17);
    ix = 3;
    for (;;) {
        q64 = (uint64_t) (uint32_t) (rem.v64>>19) * recip32;
        q = (q64 + 0x80000000)>>32;
        --ix;
        if (ix < 0) break;
        rem = softfloat_shortShiftLeft128(rem.v64, rem.v0, 29);
        term = softfloat_mul128By32(sigB.v64, sigB.v0, q);
        rem = softfloat_sub128(rem.v64, rem.v0, term.v64, term.v0);
        if (rem.v64 & UINT64_C(0x8000000000000000)) {
            --q;
            rem = softfloat_add128(rem.v64, rem.v0, sigB.v64, sigB.v0);
        }
        qs[ix] = q;
    }
    /*------------------------------------------------------------------------
    *------------------------------------------------------------------------*/
    if (((q + 1) & 7) < 2) {
        rem = softfloat_shortShiftLeft128(rem.v64, rem.v0, 29);
        term = softfloat_mul128By32(sigB.v64, sigB.v0, q);
        rem = softfloat_sub128(rem.v64, rem.v0, term.v64, term.v0);
        if (rem.v64 & UINT64_C(0x8000000000000000)) {
            --q;
            rem = softfloat_add128(rem.v64, rem.v0, sigB.v64, sigB.v0);
        } else if (softfloat_le128(sigB.v64, sigB.v0, rem.v64, rem.v0)) {
            ++q;
            rem = softfloat_sub128(rem.v64, rem.v0, sigB.v64, sigB.v0);
        }
        if (rem.v64 | rem.v0) q |= 1;
    }
    /*------------------------------------------------------------------------
    *------------------------------------------------------------------------*/
    sigZExtra = (uint64_t) ((uint64_t) q<<60);
    term = softfloat_shortShiftLeft128(0, qs[1], 54);
    sigZ = softfloat_add128((uint64_t) qs[2]<<19, ((uint64_t) qs[0]<<25) + (q>>4), term.v64, term.v0);
    return
        softfloat_roundPackToF128(signZ, expZ, sigZ.v64, sigZ.v0, sigZExtra, roundingMode, roundingPrecision, status);
    /*------------------------------------------------------------------------
    *------------------------------------------------------------------------*/
 propagateNaN:
    uiZ = softfloat_propagateNaNF128UI(uiA64, uiA0, uiB64, uiB0, status);
    return uiZ;
    /*------------------------------------------------------------------------
    *------------------------------------------------------------------------*/
 invalid:
    softfloat_raiseFlags(status, softfloat_flag_invalid);
    uiZ.v64 = defaultNaNF128UI64;
    uiZ.v0  = defaultNaNF128UI0;
    return uiZ;
    /*------------------------------------------------------------------------
    *------------------------------------------------------------------------*/
 infinity:
    uiZ.v64 = packToF128UI64(signZ, 0x7FFF, 0);
    uiZ.v0 = 0;
    return uiZ;
    /*------------------------------------------------------------------------
    *------------------------------------------------------------------------*/
 zero:
    uiZ.v64 = packToF128UI64(signZ, 0, 0);
    uiZ.v0 = 0;
    return uiZ;
}
