    sig64Extra = softfloat_shortShiftRightJam64Extra(sigZ, sigZExtra, 1);
    sigZ = sig64Extra.v | UINT64_C(0x8000000000000000);
    sigZExtra = sig64Extra.extra;
    ++expZ;
