float128_t softfloat_addMagsF128(uint64_t uiA64, uint64_t uiA0, uint64_t uiB64, uint64_t uiB0, bool signZ, uint8_t roundingMode, uint8_t roundingPrecision, struct softfloat_status_t *status)
{
    int32_t expA;
    struct uint128 sigA;
    int32_t expB;
    struct uint128 sigB;
    int32_t expDiff;
    struct uint128 uiZ, sigZ;
    int32_t expZ;
    uint64_t sigZExtra;
    struct uint128_extra sig128Extra;

    expA = expF128UI64(uiA64);
    sigA.v64 = fracF128UI64(uiA64);
    sigA.v0  = uiA0;
    expB = expF128UI64(uiB64);
    sigB.v64 = fracF128UI64(uiB64);
    sigB.v0  = uiB0;
    expDiff = expA - expB;
    if (! expDiff) {
        if (expA == 0x7FFF) {
            if (sigA.v64 | sigA.v0 | sigB.v64 | sigB.v0) goto propagateNaN;
            uiZ.v64 = uiA64;
            uiZ.v0  = uiA0;
            return uiZ;
        }
        sigZ = softfloat_add128(sigA.v64, sigA.v0, sigB.v64, sigB.v0);
        if (! expA) {
            uiZ.v64 = packToF128UI64(signZ, 0, sigZ.v64);
            uiZ.v0  = sigZ.v0;
            return uiZ;
        }
        expZ = expA;
        sigZ.v64 |= UINT64_C(0x0002000000000000);
        sigZExtra = 0;
        goto shiftRight1;
    }
    if (expDiff < 0) {
        if (expB == 0x7FFF) {
            if (sigB.v64 | sigB.v0) goto propagateNaN;
            uiZ.v64 = packToF128UI64(signZ, 0x7FFF, 0);
            uiZ.v0  = 0;
            return uiZ;
        }
        expZ = expB;
        if (expA) {
            sigA.v64 |= UINT64_C(0x0001000000000000);
        } else {
            ++expDiff;
            sigZExtra = 0;
            if (! expDiff) goto newlyAligned;
        }
        sig128Extra =
            softfloat_shiftRightJam128Extra(sigA.v64, sigA.v0, 0, -expDiff);
        sigA = sig128Extra.v;
        sigZExtra = sig128Extra.extra;
    } else {
        if (expA == 0x7FFF) {
            if (sigA.v64 | sigA.v0) goto propagateNaN;
            uiZ.v64 = uiA64;
            uiZ.v0  = uiA0;
            return uiZ;
        }
        expZ = expA;
        if (expB) {
            sigB.v64 |= UINT64_C(0x0001000000000000);
        } else {
            --expDiff;
            sigZExtra = 0;
            if (! expDiff) goto newlyAligned;
        }
        sig128Extra = softfloat_shiftRightJam128Extra(sigB.v64, sigB.v0, 0, expDiff);
        sigB = sig128Extra.v;
        sigZExtra = sig128Extra.extra;
    }
 newlyAligned:
    sigZ =
        softfloat_add128(
            sigA.v64 | UINT64_C(0x0001000000000000),
            sigA.v0,
            sigB.v64,
            sigB.v0
       );
    --expZ;
    if (sigZ.v64 < UINT64_C(0x0002000000000000)) goto roundAndPack;
    ++expZ;
 shiftRight1:
    sig128Extra = softfloat_shortShiftRightJam128Extra(sigZ.v64, sigZ.v0, sigZExtra, 1);
    sigZ = sig128Extra.v;
    sigZExtra = sig128Extra.extra;
 roundAndPack:
    return
        softfloat_roundPackToF128(signZ, expZ, sigZ.v64, sigZ.v0, sigZExtra, roundingMode, roundingPrecision, status);
 propagateNaN:
    uiZ = softfloat_propagateNaNF128UI(uiA64, uiA0, uiB64, uiB0, status);
    return uiZ;
}
