#include <stdint.h>

#ifndef softfloat_approxRecipSqrt32_1

extern const uint16_t softfloat_approxRecipSqrt_1k0s[];
extern const uint16_t softfloat_approxRecipSqrt_1k1s[];

uint32_t softfloat_approxRecipSqrt32_1(unsigned int oddExpA, uint32_t a)
{
    int index;
    uint16_t eps, r0;
    uint32_t ESqrR0;
    uint32_t sigma0;
    uint32_t r;
    uint32_t sqrSigma0;

    index = (a>>27 & 0xE) + oddExpA;
    eps = (uint16_t) (a>>12);
    r0 = softfloat_approxRecipSqrt_1k0s[index] - ((softfloat_approxRecipSqrt_1k1s[index] * (uint32_t) eps) >>20);
    ESqrR0 = (uint32_t) r0 * r0;
    if (! oddExpA) ESqrR0 <<= 1;
    sigma0 = ~(uint32_t) (((uint32_t) ESqrR0 * (uint64_t) a)>>23);
    r = ((uint32_t) r0<<16) + ((r0 * (uint64_t) sigma0)>>25);
    sqrSigma0 = ((uint64_t) sigma0 * sigma0)>>32;
    r += ((uint32_t) ((r>>1) + (r>>3) - ((uint32_t) r0<<14)) * (uint64_t) sqrSigma0) >>48;
    if (! (r & 0x80000000)) r = 0x80000000;
    return r;
}

#endif
