#include <stdbool.h>
#include <stdint.h>

extFloat80_t
 softfloat_normRoundPackToExtF80(
     bool sign,
     int32_t exp,
     uint64_t sig,
     uint64_t sigExtra,
     uint8_t roundingPrecision,
     struct softfloat_status_t *status)
{
    int8_t shiftDist;
    struct uint128 sig128;

    if (! sig) {
        exp -= 64;
        sig = sigExtra;
        sigExtra = 0;
    }
    shiftDist = softfloat_countLeadingZeros64(sig);
    exp -= shiftDist;
    if (shiftDist) {
        sig128 = softfloat_shortShiftLeft128(sig, sigExtra, shiftDist);
        sig = sig128.v64;
        sigExtra = sig128.v0;
    }
    return
        softfloat_roundPackToExtF80(sign, exp, sig, sigExtra, roundingPrecision, status);
}
